"""
title: MCP Manager Control
description: Manage json-mcp-manager via MCP — list, start, stop, restart instances, view logs, upload tools, edit code and more. Security levels are enforced server-side.
author: Torsten Feustel
version: 0.0.12
license: MIT
category: System
"""
import json
import httpx
from pydantic import BaseModel, Field


class Tools:
    # read_content refuses to pull anything bigger than this into memory.
    READ_CONTENT_MAX_BYTES = 5 * 1024 * 1024

    class Valves(BaseModel):
        manager_url: str = Field(
            default="http://127.0.0.1:7860",
            description="Base URL of the json-mcp-manager instance"
        )
        auth_token: str = Field(
            default="",
            description="Bearer token for manager authentication (leave empty if no auth)"
        )
        allow_list_instances: bool = Field(default=True, description="Allow: list all instances")
        allow_get_instance: bool = Field(default=True, description="Allow: get instance details")
        allow_start: bool = Field(default=True, description="Allow: start an instance")
        allow_stop: bool = Field(default=True, description="Allow: stop an instance")
        allow_restart: bool = Field(default=True, description="Allow: restart an instance")
        allow_reinstall: bool = Field(default=True, description="Allow: reinstall dependencies")
        allow_install_log: bool = Field(default=True, description="Allow: read install log")
        allow_runtime_log: bool = Field(default=True, description="Allow: read runtime log")
        allow_get_config: bool = Field(default=True, description="Allow: get instance config")
        allow_get_settings: bool = Field(default=True, description="Allow: get manager settings")
        allow_get_specs: bool = Field(default=True, description="Allow: read an instance's function catalog and usage")
        allow_get_usage: bool = Field(default=True, description="Allow: read usage statistics across all instances")
        allow_get_system: bool = Field(default=True, description="Allow: read CPU, memory, disk and network figures")
        allow_get_code: bool = Field(default=True, description="Allow: read tool source code")
        allow_save_code: bool = Field(default=True, description="Allow: save/edit tool source code")
        allow_validate_code: bool = Field(default=True, description="Allow: validate tool code")
        allow_export_tool: bool = Field(default=True, description="Allow: export tool as JSON")
        allow_delete: bool = Field(default=False, description="Allow: delete an instance (disabled by default)")
        allow_manager_restart: bool = Field(default=False, description="Allow: restart the manager process (disabled by default)")
        allow_get_template: bool = Field(default=True, description="Allow: get the tool code template")
        allow_upload: bool = Field(default=True, description="Allow: upload and install a new tool")
        allow_create_tool: bool = Field(default=True, description="Allow: create a new tool from raw code")
        allow_update_values: bool = Field(default=True, description="Allow: update instance valve values")
        allow_update_lifecycle: bool = Field(default=True, description="Allow: switch auto-start and restart-on-change")
        allow_update_category: bool = Field(default=True, description="Allow: update instance category metadata")
        allow_update_dependencies: bool = Field(default=True, description="Allow: update/reinstall instance dependencies")
        allow_update_venv: bool = Field(default=True, description="Allow: move an instance to another venv")
        allow_list_content: bool = Field(default=True, description="Allow: list the files instances have produced")
        allow_read_content: bool = Field(default=True, description="Allow: read a stored text file")
        allow_content_delete: bool = Field(default=False, description="Allow: delete stored files (disabled by default)")

    def __init__(self):
        self.valves = self.Valves()

    def _denied(self, valve_name: str) -> str:
        return f"Denied: '{valve_name}' is set to False in Valves. Enable it to allow this action."

    def _url(self, path: str) -> str:
        # Tolerate a trailing slash in manager_url — "http://host:7860/" would
        # otherwise produce "//api/..." paths that never match a route.
        return f"{self.valves.manager_url.rstrip('/')}{path}"

    def _headers(self) -> dict:
        h = {}
        if self.valves.auth_token:
            h["Authorization"] = f"Bearer {self.valves.auth_token}"
        return h

    def _err_detail(self, r) -> str:
        try:
            detail = r.json().get("detail", "")
        except Exception:
            detail = (r.text or "")[:300]
        if isinstance(detail, (dict, list)):
            return json.dumps(detail, ensure_ascii=False)
        return str(detail) or "no detail provided"

    def _get(self, path: str, timeout: int = 10) -> str:
        try:
            r = httpx.get(self._url(path), headers=self._headers(), timeout=timeout)
            if r.status_code == 401:
                return "Error: Authentication required. Set auth_token in Valves."
            if r.status_code == 403:
                return f"Error: Forbidden (403) — {self._err_detail(r)}"
            if r.status_code >= 400:
                return f"Error {r.status_code}: {self._err_detail(r)}"
            try:
                return json.dumps(r.json(), indent=2)
            except Exception:
                return r.text
        except httpx.ConnectError:
            return f"Error: Cannot connect to manager at {self.valves.manager_url}"
        except Exception as e:
            return f"Error: {type(e).__name__}: {e}" if str(e) else f"Error: {type(e).__name__}"

    def _post(self, path: str, data: dict = None, timeout: int = 60) -> str:
        try:
            r = httpx.post(
                self._url(path),
                headers=self._headers(),
                json=data or {},
                timeout=timeout
            )
            if r.status_code == 401:
                return "Error: Authentication required. Set auth_token in Valves."
            if r.status_code == 403:
                return f"Error: Forbidden (403) — {self._err_detail(r)}"
            if r.status_code >= 400:
                return f"Error {r.status_code}: {self._err_detail(r)}"
            try:
                return json.dumps(r.json(), indent=2)
            except Exception:
                return r.text
        except httpx.ConnectError:
            return f"Error: Cannot connect to manager at {self.valves.manager_url}"
        except Exception as e:
            return f"Error: {type(e).__name__}: {e}" if str(e) else f"Error: {type(e).__name__}"

    def _put(self, path: str, data: dict, timeout: int = 60) -> str:
        try:
            r = httpx.put(
                self._url(path),
                headers=self._headers(),
                json=data,
                timeout=timeout
            )
            if r.status_code == 401:
                return "Error: Authentication required. Set auth_token in Valves."
            if r.status_code == 403:
                return f"Error: Forbidden (403) — {self._err_detail(r)}"
            if r.status_code >= 400:
                return f"Error {r.status_code}: {self._err_detail(r)}"
            try:
                return json.dumps(r.json(), indent=2)
            except Exception:
                return r.text
        except httpx.ConnectError:
            return f"Error: Cannot connect to manager at {self.valves.manager_url}"
        except Exception as e:
            return f"Error: {type(e).__name__}: {e}" if str(e) else f"Error: {type(e).__name__}"

    def _delete(self, path: str, timeout: int = 30) -> str:
        try:
            r = httpx.delete(
                self._url(path),
                headers=self._headers(),
                timeout=timeout
            )
            if r.status_code == 401:
                return "Error: Authentication required. Set auth_token in Valves."
            if r.status_code == 403:
                return f"Error: Forbidden (403) — {self._err_detail(r)}"
            if r.status_code >= 400:
                return f"Error {r.status_code}: {self._err_detail(r)}"
            try:
                return json.dumps(r.json(), indent=2)
            except Exception:
                return r.text
        except httpx.ConnectError:
            return f"Error: Cannot connect to manager at {self.valves.manager_url}"
        except Exception as e:
            return f"Error: {type(e).__name__}: {e}" if str(e) else f"Error: {type(e).__name__}"

    def list_instances(self) -> str:
        """List all MCP server instances with their status, port and URL."""
        if not self.valves.allow_list_instances:
            return self._denied("allow_list_instances")
        return self._get("/api/instances")

    def get_instance(self, instance_id: str) -> str:
        """Get status and details of a specific MCP server instance.

        Args:
            instance_id: The instance ID (e.g. 'openhab', 'calculator')
        """
        if not self.valves.allow_get_instance:
            return self._denied("allow_get_instance")
        return self._get(f"/api/instances/{instance_id}")

    def start_instance(self, instance_id: str) -> str:
        """Start an MCP server instance.

        Args:
            instance_id: The instance ID to start
        """
        if not self.valves.allow_start:
            return self._denied("allow_start")
        return self._post(f"/api/instances/{instance_id}/start")

    def stop_instance(self, instance_id: str) -> str:
        """Stop a running MCP server instance.

        Args:
            instance_id: The instance ID to stop
        """
        if not self.valves.allow_stop:
            return self._denied("allow_stop")
        return self._post(f"/api/instances/{instance_id}/stop")

    def restart_instance(self, instance_id: str) -> str:
        """Restart an MCP server instance.

        Fails with 403 while the instance is locked in the web UI (stop and
        start still work on a locked instance).

        Args:
            instance_id: The instance ID to restart
        """
        if not self.valves.allow_restart:
            return self._denied("allow_restart")
        return self._post(f"/api/instances/{instance_id}/restart")

    def reinstall_instance(self, instance_id: str) -> str:
        """Reinstall dependencies for an MCP server instance. Can take minutes for large packages.

        Fails with 403 while the instance is locked in the web UI.

        Args:
            instance_id: The instance ID to reinstall
        """
        if not self.valves.allow_reinstall:
            return self._denied("allow_reinstall")
        return self._post(f"/api/instances/{instance_id}/reinstall", timeout=600)

    def get_install_log(self, instance_id: str) -> str:
        """Get the installation log for an MCP server instance.

        Args:
            instance_id: The instance ID
        """
        if not self.valves.allow_install_log:
            return self._denied("allow_install_log")
        return self._get(f"/api/instances/{instance_id}/logs/install")

    def get_runtime_log(self, instance_id: str) -> str:
        """Get the runtime log for an MCP server instance.

        Args:
            instance_id: The instance ID
        """
        if not self.valves.allow_runtime_log:
            return self._denied("allow_runtime_log")
        return self._get(f"/api/instances/{instance_id}/logs/runtime")

    def get_instance_config(self, instance_id: str) -> str:
        """Get the full configuration of an MCP server instance including values.

        Args:
            instance_id: The instance ID
        """
        if not self.valves.allow_get_config:
            return self._denied("allow_get_config")
        return self._get(f"/api/instances/{instance_id}/config")

    def get_settings(self) -> str:
        """Get current manager settings: auth status, edit mode, host, port and MCP token status."""
        if not self.valves.allow_get_settings:
            return self._denied("allow_get_settings")
        return self._get("/api/settings")

    def get_instance_specs(self, instance_id: str) -> str:
        """List the functions one instance provides, with parameters and usage.

        Returns every function of the instance — name, description and the full
        parameter schema — plus how often this instance has been used, when
        last and which function that was. Read from the tool's stored specs, so
        it works even while the instance is stopped.

        Use this to find out what a tool can actually do before calling it, or
        to check whether its descriptions are complete.

        Args:
            instance_id: The instance ID (e.g. 'openhab', 'gesetze_im_internet')
        """
        if not self.valves.allow_get_specs:
            return self._denied("allow_get_specs")
        return self._get(f"/api/instances/{instance_id}/specs")

    def get_usage_stats(self, days: int = 7) -> str:
        """Usage statistics over all instances — what gets used, and what never.

        For every known instance: calls within the given window, calls in total,
        first and last use, the function used last, a per-day series, and the
        same numbers broken down per function. Instances that were never used
        are included with zeros — that is the point of the report.

        Sorted by the calls within the window, not by the total: the total
        favours whatever has been installed longest. Note that the manager
        control tool and a tool router count their own traffic too, so they
        rank high without being tools anyone deliberately uses.

        Args:
            days: Length of the window in days (default 7)
        """
        if not self.valves.allow_get_usage:
            return self._denied("allow_get_usage")
        return self._get(f"/api/usage?days={int(days)}")

    def get_system_stats(self, instance_id: str = "", top: int = 10) -> str:
        """What the machine and the instances are costing right now.

        Without arguments: one line for the machine — CPU, memory, disk and the
        current network rate — followed by the instances that use the most
        memory. With an instance id: only that instance's figures.

        Memory is the instance's whole process tree, its child processes
        included, so a tool that shells out is charged for what it started.
        A figure shown as '?' has not been measured yet (rates and per-process
        CPU need a previous sample) and is not the same as zero. If the manager
        cannot measure at all, the answer says so and gives the reason — that
        reason is the whole answer, do not offer another one.

        Args:
            instance_id: Optional — report only this instance
            top: How many instances to list, heaviest first (default 10)
        """
        if not self.valves.allow_get_system:
            return self._denied("allow_get_system")
        data = self._json_get("/api/system/stats")
        if not isinstance(data, dict):
            return data
        if not data.get("available"):
            reason = data.get("reason") or "the manager did not say why"
            return "No system figures available: " + reason

        instances = data.get("instances") or {}
        if instance_id:
            stats = instances.get(instance_id)
            if not stats:
                measured = ", ".join(sorted(instances)) or "none"
                return ("No figures for '" + instance_id + "' — only running instances are "
                        "measured. Currently measured: " + measured)
            return instance_id + ": " + self._process_line(stats)

        machine = data.get("machine") or {}
        lines = [self._machine_line(machine), self._disk_line(machine)]
        rows = sorted(instances.items(), key=lambda kv: kv[1].get("rss") or 0, reverse=True)
        if not rows:
            lines.append("No instance is running, so there is nothing to measure per instance.")
            return "\n".join(lines)
        limit = max(1, int(top))
        lines.append("{} running instance(s), heaviest first:".format(len(rows)))
        for name, stats in rows[:limit]:
            lines.append("- {}: {}".format(name, self._process_line(stats)))
        if len(rows) > limit:
            lines.append("... {} more not shown — raise 'top' to see them.".format(len(rows) - limit))
        return "\n".join(lines)

    def _size(self, value) -> str:
        """Bytes at any scale — a disk reaches TB while a process stays in MB."""
        if value is None:
            return "?"
        size = float(value)
        if size < 1024:
            return "{:.0f} B".format(size)
        for unit in ("KB", "MB", "GB"):
            size /= 1024
            if size < 1024:
                return "{:.1f} {}".format(size, unit)
        return "{:.1f} TB".format(size / 1024)

    def _percent(self, value) -> str:
        return "?" if value is None else "{:.0f} %".format(value)

    def _rate(self, value) -> str:
        return "?" if value is None else self._size(value) + "/s"

    def _machine_line(self, machine: dict) -> str:
        memory = machine.get("memory") or {}
        network = machine.get("network") or {}
        cores = machine.get("cpu_count")
        cpu = "CPU " + self._percent(machine.get("cpu_percent"))
        if cores:
            cpu += " of {} cores".format(cores)
        return " · ".join([
            "Machine: " + cpu,
            "RAM {} of {} ({})".format(self._size(memory.get("used")),
                                       self._size(memory.get("total")),
                                       self._percent(memory.get("percent"))),
            "Net up {}, down {}".format(self._rate(network.get("up_bps")),
                                        self._rate(network.get("down_bps"))),
        ])

    def _disk_line(self, machine: dict) -> str:
        """Every mounted drive, not only the one the manager is installed on.

        Its own line rather than a fourth item on the machine line: a machine
        with three drives would otherwise push the whole sentence past the
        width anyone reads.
        """
        disks = machine.get("disks")
        if not disks:
            one = machine.get("disk") or {}
            disks = [dict(one, install=True)] if one else []
        if not disks:
            return "Disks: not reported"
        parts = []
        for disk in disks:
            where = disk.get("mount") or "?"
            note = " — installation" if disk.get("install") and len(disks) > 1 else ""
            parts.append("{} {} free of {} ({} used{})".format(
                where, self._size(disk.get("free")), self._size(disk.get("total")),
                self._percent(disk.get("percent")), note))
        return "Disks: " + " · ".join(parts)

    def _process_line(self, stats: dict) -> str:
        count = int(stats.get("processes") or 1)
        return "{} RAM · {} CPU · {} process{}".format(
            self._size(stats.get("rss")), self._percent(stats.get("cpu_percent")),
            count, "" if count == 1 else "es")

    def get_tool_code(self, instance_id: str) -> str:
        """Get the Python source code of an MCP server tool. Requires full edit mode.

        Args:
            instance_id: The instance ID
        """
        if not self.valves.allow_get_code:
            return self._denied("allow_get_code")
        return self._get(f"/api/instances/{instance_id}/tool-code")

    def save_tool_code(self, instance_id: str, code: str) -> str:
        """Replace the Python code of an EXISTING instance — this is the 'edit code' action.

        Use this (NOT upload_tool) whenever an instance with this ID already exists,
        e.g. to fix a bug, add a comment or add a method. The manager validates the
        code before saving and rejects invalid code with an error list. On success
        the instance restarts automatically, so the change is live immediately.
        Requires full edit mode. Fails with 403 while the instance is locked in
        the web UI — this also protects the manager control tool from editing
        its own code while it is locked.

        Args:
            instance_id: The instance ID whose code to replace
            code: The complete new Python source code (the full file, not a diff)
        """
        if not self.valves.allow_save_code:
            return self._denied("allow_save_code")
        # Long timeout: the manager installs newly declared dependencies before validating.
        return self._put(f"/api/instances/{instance_id}/tool-code", {"code": code}, timeout=600)

    def validate_tool_code(self, code: str, instance_id: str = "") -> str:
        """Validate Python tool code: syntax check, runtime inspection and schema generation.

        ALWAYS call this before upload_tool or save_tool_code and fix every reported
        error first — the manager rejects invalid code anyway, so validating early
        saves a round trip. Returns valid, errors, warnings, the generated tool
        specs and the Valves defaults. Requires full edit mode.

        Args:
            code: The Python source code to validate
            instance_id: Optional — validate in this instance's venv so its installed
                third-party dependencies resolve (recommended when editing an
                existing instance; older managers ignore this parameter)
        """
        if not self.valves.allow_validate_code:
            return self._denied("allow_validate_code")
        body = {"code": code}
        if instance_id:
            body["instance_id"] = instance_id
        return self._post("/api/tools/validate", body)

    def export_tool(self, instance_id: str, name: str, description: str) -> str:
        """Export an MCP server tool as OpenWebUI-compatible JSON.

        Requires full edit mode and permission to read tool source code
        (allow_get_code), because the export is built from the instance's code.

        Args:
            instance_id: The instance ID (used as tool id)
            name: Display name for the exported tool
            description: Short description of the tool
        """
        if not self.valves.allow_export_tool:
            return self._denied("allow_export_tool")
        if not self.valves.allow_get_code:
            return self._denied("allow_get_code")
        code_result = self._get(f"/api/instances/{instance_id}/tool-code")
        if code_result.startswith("Error"):
            return code_result
        try:
            code = json.loads(code_result)["code"]
        except (json.JSONDecodeError, KeyError):
            return "Error: Unexpected response format from tool-code endpoint"
        return self._post("/api/tools/export", {
            "code": code,
            "id": instance_id,
            "name": name,
            "description": description
        })

    def delete_instance(self, instance_id: str) -> str:
        """Delete an MCP server instance and its config.

        Requires upload or full edit mode. Fails with 403 while the instance is
        locked in the web UI.

        Args:
            instance_id: The instance ID to delete
        """
        if not self.valves.allow_delete:
            return self._denied("allow_delete")
        return self._delete(f"/api/instances/{instance_id}")

    def restart_manager(self) -> str:
        """Restart the json-mcp-manager process. The manager will come back up automatically."""
        if not self.valves.allow_manager_restart:
            return self._denied("allow_manager_restart")
        return self._post("/api/server/restart")

    def get_tool_template(self) -> str:
        """Returns the Python code template AND the complete JSON upload format.

        Always call this before writing or uploading a new tool.
        The response contains two sections:
        1. The Python code template (for the 'content' field in the upload JSON)
        2. The exact JSON array format that upload_tool() expects
        """
        if not self.valves.allow_get_template:
            return self._denied("allow_get_template")
        template = self._get("/api/tools/template")
        if template.startswith("Error"):
            return template
        json_example = json.dumps([
            {
                "id": "my_tool",
                "user_id": "00000000-0000-0000-0000-000000000000",
                "name": "My Tool",
                "meta": {
                    "description": "Short description shown in UI and to the AI",
                    "manifest": {
                        "title": "My Tool",
                        "author": "Your Name",
                        "version": "0.1.0"
                    }
                },
                "specs": [
                    {
                        "name": "my_function",
                        "description": "What this function does",
                        "parameters": {
                            "type": "object",
                            "properties": {
                                "param": {
                                    "type": "string",
                                    "description": "Description of this parameter"
                                }
                            },
                            "required": ["param"]
                        }
                    }
                ],
                "content": "# Replace this with the Python code from the template above"
            }
        ], indent=2)
        return (
            "=== PYTHON CODE TEMPLATE (use as 'content' field) ===\n\n"
            + template
            + "\n\n=== UPLOAD JSON FORMAT ===\n"
            + "upload_tool() expects a JSON array (not an object). Each element has:\n"
            + "  id       — unique snake_case identifier (becomes the MCP server ID)\n"
            + "  user_id  — always '00000000-0000-0000-0000-000000000000'\n"
            + "  name     — display name\n"
            + "  meta     — {description, manifest: {title, author, version}}\n"
            + "  specs    — list of tool definitions matching the methods in your Tools class\n"
            + "  content  — the complete Python source code as a string\n\n"
            + "Category is manager metadata: pass it as upload_tool(..., category=...) "
            + "instead of adding it to this JSON.\n\n"
            + "Example:\n"
            + json_example
        )

    def upload_tool(self, json_content: str, category: str = "") -> str:
        """Create and install a NEW tool instance from a JSON definition.

        Only for NEW tools: fails if the ID already exists — in that case use
        save_tool_code(instance_id, code) to change the existing tool instead.
        The manager validates the Python code on upload and rejects invalid code
        with an error list. Requires upload or full edit mode.

        Workflow for a new tool:
        1. get_tool_template() — get the exact JSON format and code template
        2. validate_tool_code(code) — repeat until there are no errors
        3. upload_tool(json_content, category) — JSON must be an array; category is
           stored separately as manager metadata and never inserted into the JSON
        4. start_instance(id) — uploaded instances do not start automatically

        Args:
            json_content: JSON array string — call get_tool_template() to see the format
            category: Optional manager category (for example "Smart Home"); not written into the JSON
        """
        if not self.valves.allow_upload:
            return self._denied("allow_upload")
        try:
            json.loads(json_content)
        except json.JSONDecodeError:
            return "Error: Invalid JSON content provided"
        try:
            headers = {}
            if self.valves.auth_token:
                headers["Authorization"] = f"Bearer {self.valves.auth_token}"
            form_data = {}
            if category.strip():
                form_data["category"] = category.strip()
            r = httpx.post(
                self._url("/api/instances/upload"),
                headers=headers,
                files={"file": ("tool.json", json_content.encode(), "application/json")},
                data=form_data,
                timeout=600
            )
            if r.status_code == 401:
                return "Error: Authentication required. Set auth_token in Valves."
            if r.status_code == 403:
                return f"Error: Forbidden (403) — {self._err_detail(r)}"
            if r.status_code >= 400:
                return f"Error {r.status_code}: {self._err_detail(r)}"
            return json.dumps(r.json(), indent=2)
        except httpx.ConnectError:
            return f"Error: Cannot connect to manager at {self.valves.manager_url}"
        except Exception as e:
            return f"Error: {type(e).__name__}: {e}" if str(e) else f"Error: {type(e).__name__}"

    def create_tool(self, code: str, id: str, name: str = "", description: str = "", category: str = "", requirements: str = "", venv: str = "default", port: int = 0) -> str:
        """Create and install a NEW instance from raw Python code in ONE step.

        Preferred over upload_tool: pass the plain Python source (no JSON
        wrapping, no specs). The manager installs dependencies, validates the
        code in the instance's venv, fills the Valve defaults into the editable
        config and saves it. Dependencies come from the `requirements:` line in
        the code's docstring, or pass them explicitly as a comma-separated
        string. The new instance does NOT auto-start — call start_instance(id)
        afterwards. Fails if the ID already exists (use save_tool_code to modify
        an existing tool). Requires upload or full edit mode.

        Args:
            code: The complete Python source code (the full file)
            id: Unique snake_case identifier (becomes the MCP server ID)
            name: Display name (defaults to the ID)
            description: Short description shown in the UI and to the AI
            category: Optional manager category (for example "Utilities")
            requirements: Optional comma-separated pip packages (overrides the docstring)
            venv: Virtual-env name to install into (default: "default")
            port: Optional fixed port (1024-65535); omit/0 to auto-assign
        """
        if not self.valves.allow_create_tool:
            return self._denied("allow_create_tool")
        body = {
            "id": id, "code": code, "name": name,
            "description": description, "category": category, "venv": venv,
        }
        if requirements and requirements.strip():
            body["requirements"] = requirements
        if port:
            body["port"] = port
        # Long timeout: dependency install + venv creation can take minutes.
        return self._post("/api/tools/create", body, timeout=600)

    def update_instance_category(self, instance_id: str, category: str) -> str:
        """Set, change or clear the manager category of an existing instance.

        Category is display/filter metadata in the MCP manager. It does not
        modify the tool JSON or Python code and does not require a restart.
        Pass an empty string to remove the category. Requires upload or full
        edit mode and fails with 403 while the instance is locked in the web UI.

        Args:
            instance_id: The instance ID to update
            category: New category, or an empty string to clear it
        """
        if not self.valves.allow_update_category:
            return self._denied("allow_update_category")
        return self._put(f"/api/instances/{instance_id}", {"category": category})

    def update_instance_values(self, instance_id: str, values: dict) -> str:
        """Set/merge Valve values (configuration) of an existing instance.

        Merges the given keys into the instance's editable config values, e.g.
        an API key or a base URL. Other values are kept (send only the keys you
        want to change). Requires upload or full edit mode and fails with 403
        while the instance is locked in the web UI.

        Only the tool's **own valves** are accepted here; a name that is not one
        is refused, and the refusal lists the valves this instance has. In
        particular auto_start and restart_on_change are not valves — they are
        set with update_instance_lifecycle.

        The manager normally restarts a running instance automatically when
        restart_on_change is enabled. The response states whether that restart
        happened. Only ask about a manual restart when the manager did not
        restart an instance that is currently running.

        Args:
            instance_id: The instance ID to update
            values: Mapping of valve name to value (only the keys to change)
        """
        if not self.valves.allow_update_values:
            return self._denied("allow_update_values")
        result = self._put(f"/api/instances/{instance_id}", {"values": values})
        if result.startswith("Error"):
            return result
        try:
            restarted = bool(json.loads(result).get("restarted"))
        except (json.JSONDecodeError, AttributeError):
            return "Error: Unexpected response format from instance update endpoint"
        if restarted:
            return result + "\n\nValues saved and the running instance was already restarted by the manager."
        return (
            result
            + "\n\nValues saved. The manager did not restart the instance. "
            + "If it is currently running, ask the user whether to restart '"
            + instance_id + "' now."
        )

    def update_instance_lifecycle(self, instance_id: str, auto_start: str = "", restart_on_change: str = "") -> str:
        """Switch an instance's auto-start and restart-on-change on or off.

        auto_start — start this instance automatically when the manager starts.
        restart_on_change — restart it by itself after its configuration changed.

        These two are **not** Valve values. Do not try to set them through
        update_instance_values: that call takes only the tool's own valves and
        refuses a name that is not one.

        Pass "true" or "false" for the setting you want to change and leave the
        other empty — an empty argument means "leave it as it is".

        Args:
            instance_id: The instance ID to update
            auto_start: "true", "false", or empty to leave unchanged
            restart_on_change: "true", "false", or empty to leave unchanged
        """
        if not self.valves.allow_update_lifecycle:
            return self._denied("allow_update_lifecycle")

        lifecycle = {}
        for field, raw in (("auto_start", auto_start), ("restart_on_change", restart_on_change)):
            text = str(raw).strip().lower()
            if not text:
                continue
            if text in ("true", "yes", "on", "1"):
                lifecycle[field] = True
            elif text in ("false", "no", "off", "0"):
                lifecycle[field] = False
            else:
                return ("Error: " + field + " must be \"true\" or \"false\" (got " + repr(raw)
                        + "). Leave it empty to keep the current setting.")
        if not lifecycle:
            return ("Nothing to change — pass \"true\" or \"false\" for auto_start "
                    "and/or restart_on_change.")

        result = self._put("/api/instances/" + instance_id, {"lifecycle": lifecycle})
        if result.startswith("Error"):
            return result
        settings = ", ".join(k + " = " + str(v).lower() for k, v in sorted(lifecycle.items()))
        return "'" + instance_id + "' updated: " + settings + "."

    def update_instance_dependencies(self, instance_id: str, dependencies: list) -> str:
        """Replace the pip dependencies of an existing instance and reinstall them.

        Sets install.dependencies to the given list. The manager prepares the
        instance venv as part of the update and restarts a running instance when
        required; no second reinstall request is sent. Requires upload or full
        edit mode and fails with 403 while the instance is locked in the web UI.

        Args:
            instance_id: The instance ID to update
            dependencies: Full list of pip package specs (replaces the old list)
        """
        if not self.valves.allow_update_dependencies:
            return self._denied("allow_update_dependencies")
        # The PUT performs the dependency install itself; calling /reinstall
        # afterwards would install the same packages a second time.
        return self._put(
            f"/api/instances/{instance_id}",
            {"install": {"dependencies": dependencies}},
            timeout=600,
        )

    def update_instance_venv(self, instance_id: str, venv: str) -> str:
        """Move an instance to a different virtual environment (venv).

        Sets the instance's venv, (re)installs its dependencies there and — if the
        instance is running — restarts it so the change applies immediately. The
        target venv is created automatically if it does not exist yet. Requires
        upload or full edit mode and fails with 403 while the instance is locked
        in the web UI.

        Args:
            instance_id: The instance ID to move
            venv: Target venv name (created on demand; letters, digits, _ and -)
        """
        if not self.valves.allow_update_venv:
            return self._denied("allow_update_venv")
        # Long timeout: venv creation + dependency install + restart can take minutes.
        return self._put(f"/api/instances/{instance_id}", {"venv": venv}, timeout=600)


    def _content_url(self, url: str) -> str:
        """Absolute URL for a download link that may have come back relative.

        The manager only builds absolute links once an admin has set the
        download base URL. Without it the listing still carries a usable path,
        and the manager is where we are talking anyway.
        """
        if url.startswith("http://") or url.startswith("https://"):
            return url
        return self._url(url)

    def _json_get(self, path: str):
        raw = self._get(path)
        try:
            return json.loads(raw)
        except Exception:
            return raw  # an error string from _get — hand it back as it is

    def list_content(self, instance_id: str = "") -> str:
        """List the files instances have produced, or the files of one instance.

        Without an instance: one line per instance with a folder — how many
        files, how much space, and how old the oldest one is. With an instance:
        that folder's files with size, age and a download link.

        The link is the way to hand a file to a user: it carries a token for
        that one file and works in a browser without a login.

        Args:
            instance_id: Optional — the instance whose files to list
        """
        if not self.valves.allow_list_content:
            return self._denied("allow_list_content")
        import time

        def age(ts) -> str:
            if not ts:
                return "?"
            days = int((time.time() - ts) / 86400)
            return "today" if days < 1 else f"{days} d old"

        if instance_id:
            data = self._json_get(f"/api/content/{instance_id}")
            if not isinstance(data, dict):
                return data
            items = data.get("items") or []
            if not items:
                return f"'{instance_id}' has no stored files."
            lines = [f"{len(items)} file(s) in '{instance_id}', {self._mb(data.get('bytes', 0))}:"]
            for item in items:
                lines.append(
                    f"- {item['name']} · {self._mb(item['size'])} · {age(item.get('modified'))}"
                    f" · {self._content_url(item['url'])}"
                )
            return "\n".join(lines)

        data = self._json_get("/api/content")
        if not isinstance(data, dict):
            return data
        entries = data.get("instances") or []
        if not entries:
            return "No instance has stored any files."
        lines = [f"{data.get('total_files', 0)} file(s), {self._mb(data.get('total_bytes', 0))} in total:"]
        for entry in entries:
            quota = f" · {entry['percent']} % of quota" if entry.get("limit_bytes") else ""
            lines.append(
                f"- {entry['instance']}: {entry['files']} file(s), {self._mb(entry['bytes'])}"
                f"{quota} · oldest {age(entry.get('oldest'))}"
            )
        lines.append("Call list_content with an instance_id for the file names and links.")
        return "\n".join(lines)

    def _mb(self, size: int) -> str:
        size = int(size or 0)
        if size < 1024:
            return f"{size} B"
        if size < 1024 * 1024:
            return f"{size / 1024:.0f} KB"
        return f"{size / (1024 * 1024):.1f} MB"

    def read_content(self, instance_id: str, filename: str, max_chars: int = 8000) -> str:
        """Read a stored text file. Binary files are described, not dumped.

        A .docx or a .png in a chat window helps nobody and costs the whole
        context window — for those you get the type, the size and the download
        link to hand to the user instead.

        Args:
            instance_id: The instance the file belongs to
            filename: The file name as listed by list_content
            max_chars: Cut the text off after this many characters (default 8000)
        """
        if not self.valves.allow_read_content:
            return self._denied("allow_read_content")
        data = self._json_get(f"/api/content/{instance_id}")
        if not isinstance(data, dict):
            return data
        match = next((i for i in (data.get("items") or []) if i["name"] == filename), None)
        if match is None:
            return f"No file '{filename}' in the storage of '{instance_id}'."
        url = self._content_url(match["url"])
        # Decided from the listing's size, before any bytes move: fetching a
        # multi-gigabyte export just to answer "that is binary, here is the
        # link" would buffer the whole file in this tool's memory.
        size = int(match.get("size") or 0)
        if size > self.READ_CONTENT_MAX_BYTES:
            return (
                f"'{filename}' is {self._mb(size)} — too large to read into the chat. "
                f"Give the user this link instead: {url}"
            )
        try:
            r = httpx.get(url, timeout=30)
            if r.status_code >= 400:
                return f"Error {r.status_code}: could not fetch '{filename}'"
            raw = r.content
        except Exception as e:
            return f"Error: {type(e).__name__}: {e}" if str(e) else f"Error: {type(e).__name__}"

        # Two ways a file says "I am not text": a NUL byte, or bytes that are
        # not valid UTF-8. Either one is enough to stop here.
        if b"\x00" in raw[:4096]:
            text = None
        else:
            try:
                text = raw.decode("utf-8")
            except UnicodeDecodeError:
                text = None
        if text is None:
            kind = filename.rsplit(".", 1)[-1].lower() if "." in filename else "unknown"
            return (
                f"'{filename}' is a binary {kind} file ({self._mb(len(raw))}), not text. "
                f"Give the user this link instead: {url}"
            )
        if len(text) > max_chars:
            return text[:max_chars] + f"\n\n[cut off after {max_chars} characters of {len(text)}]"
        return text

    def delete_content(self, instance_id: str, filename: str = "") -> str:
        """Delete a stored file, or every file of one instance.

        Disabled by default (allow_content_delete) and refused by the manager
        as well while it runs in read-only mode. A deleted file's link stops
        working immediately — that is how access to a file is withdrawn.

        Args:
            instance_id: The instance the file belongs to
            filename: The file to delete; empty means every file of that instance
        """
        if not self.valves.allow_content_delete:
            return self._denied("allow_content_delete")
        if filename:
            return self._delete(f"/api/content/{instance_id}/{filename}")
        return self._delete(f"/api/content/{instance_id}")
